 using System;
 using System.Collections.Generic;
 using SolidFramework;
 using System.IO;
	namespace SolidPoc
	{
		class Program
		{
			static void Main(string[] args)
			{
				License.Import(new StreamReader(@"lincense.xml"));
				using (PdfToTextConverter converter as new PdfToTextConverter)
				{
					ConversionStatus returnStatus = converter.Convert(@"c:\temp\MyFile.pdf", @"c:\output\MyFile.txt", true);
				}
			}
		}
	}
